<?php require_once __DIR__.'/../core_php/extractor.php'; $rows=[]; if($_SERVER['REQUEST_METHOD']==='POST'){foreach(preg_split('/\R+/',$_POST['urls']??'') as $url){$url=trim($url);if(!$url)continue;$html=fetchPage($url);foreach(extractEmails($html) as $email)$rows[]=[$email,extractPageTitle($html),$url,validateEmail($email)];}} ?><!doctype html><html><head><meta charset="utf-8"><title>Chimera Email Extractor</title><style>body{font-family:sans-serif;margin:2rem}textarea{width:100%;height:100px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:.4rem}</style></head><body><h1>Chimera Email Extractor</h1><form method="post"><textarea name="urls" placeholder="URLs, one per line"></textarea><button>Search Now</button></form><p>Pages and contacts are processed server-side. Results: <?=count($rows)?></p><table><tr><th>Email</th><th>Page Title</th><th>Website</th><th>MX</th></tr><?php foreach($rows as $r): ?><tr><td><?=htmlspecialchars($r[0])?></td><td><?=htmlspecialchars($r[1])?></td><td><?=htmlspecialchars($r[2])?></td><td><?=$r[3]?'YES':'NO'?></td></tr><?php endforeach;?></table></body></html>
